// silkgen converts a designer-produced .silkui file into a Go source
// snippet using silk/decl's builder DSL. Wraps the snippet in a
// minimal Go file with package + imports + a build function so the
// output is drop-in compilable.
//
// Usage:
//
//	silkgen path/to/main.silkui                # writes to stdout
//	silkgen -o gen.silk.go path/to/main.silkui  # writes to a file
//	silkgen -package mypkg main.silkui          # custom package name
//	silkgen -func BuildMain main.silkui         # custom function name
//
// The output skeleton:
//
//	// Code generated by silkgen — DO NOT EDIT.
//	package <package>
//
//	import "github.com/uk0/silk/decl"
//
//	func <Func>() *decl.Node {
//	    return decl.Form(...)
//	}
//
// Re-running silkgen on the same .silkui yields byte-identical output
// (subject to gofmt). This makes the tool safe to wire into go:generate
// directives.
package main

import (
	"errors"
	"flag"
	"fmt"
	"io"
	"os"

	"github.com/uk0/silk/core"
	"github.com/uk0/silk/decl"
	"github.com/uk0/silk/macro"
)

func main() { os.Exit(run(os.Args[1:])) }

func run(args []string) int {
	defer core.Close()
	flags := flag.NewFlagSet("silkgen", flag.ContinueOnError)
	var (
		macroMode   = flags.Bool("macro", false, "expand .silkgo macros into standard Go (no code execution)")
		outFile     = flags.String("o", "", "write output to file (default stdout)")
		packageName = flags.String("package", "ui", "package name in the generated file")
		funcName    = flags.String("func", "", "function name (default Build<Stem> derived from input filename)")
	)
	flags.Usage = func() {
		fmt.Fprintln(os.Stderr, "usage: silkgen [-o out.go] [-package P] [-func F] input.silkui\n       silkgen -macro [-o generated.go] input.silkgo")
		flags.PrintDefaults()
	}
	if err := flags.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			return 0
		}
		return 2
	}
	if flags.NArg() != 1 {
		flags.Usage()
		return 2
	}
	in := flags.Arg(0)

	if *macroMode {
		f, err := os.Open(in)
		if err != nil {
			return fail("read %s: %v", in, err)
		}
		src, err := io.ReadAll(io.LimitReader(f, macro.MaxSourceBytes+1))
		f.Close()
		if err != nil {
			return fail("read %s: %v", in, err)
		}
		generated, err := macro.Expand(in, src)
		if err != nil {
			return fail("%v", err)
		}
		if *outFile == "" {
			if _, err := os.Stdout.Write(generated); err != nil {
				return fail("write: %v", err)
			}
			return 0
		}
		if err := macro.WriteFile(*outFile, generated); err != nil {
			return fail("%v", err)
		}
		return 0
	}

	// Load the .silkui via core's TDoc parser, then convert to AST.
	doc, err := core.LoadTDocFile(in)
	if err != nil {
		return fail("read %s: %v", in, err)
	}
	tree, err := decl.FromTDoc(doc)
	if err != nil {
		return fail("parse %s: %v", in, err)
	}
	formatted, err := generateSource(in, *packageName, *funcName, tree)
	if err != nil {
		return fail("generate %s: %v", in, err)
	}

	if *outFile == "" {
		if _, err := os.Stdout.Write(formatted); err != nil {
			return fail("write stdout: %v", err)
		}
		return 0
	}
	if err := os.WriteFile(*outFile, formatted, 0644); err != nil {
		return fail("write %s: %v", *outFile, err)
	}
	return 0
}

func fail(format string, args ...interface{}) int {
	fmt.Fprintf(os.Stderr, "silkgen: "+format+"\n", args...)
	return 1
}
